SELECT COUNT(1) FROM `dorm_check`
WHERE deleted =0

    AND check_time >= #{startDateTime}
    AND check_time  <=  #{endDateTime}


    AND status = #{status}


    AND abnormal_type = #{abnormalType}


    AND check_status = #{checkStatus}

SELECT COUNT(1) FROM `dorm_check`
WHERE deleted =0

    AND check_time >= #{startDateTime}
    AND check_time  <=  #{endDateTime}


    AND check_status != #{checkStatus}

SELECT COUNT(1) FROM `dorm_check`
WHERE deleted =0

    AND check_time >= #{startDateTime}
    AND check_time  <=  #{endDateTime}


    AND check_status != #{checkStatus}


    AND className = #{className}

SELECT abnormal_type, count(1) AS count FROM dorm_check
WHERE deleted = 0 AND `status` = #{status}

    AND DATE_FORMAT(check_time,'%Y-%m-%d') = #{checkTime}

GROUP BY abnormal_type

SELECT
    ROUND(SUM(IF(check_status = 0, 1, 0)) / COUNT(1),2) AS inRate,
    SUM(IF(check_status !=  0, 1, 0)) AS abnormalCount
FROM dorm_check WHERE
student_id IN (
    SELECT id FROM student_info WHERE class_name=#{className}
)

    AND DATE_FORMAT(check_time,'%Y-%m-%d') = #{checkTime}
